def solve(rows):
    state = 9
    kept_rows = []
    original_index = 0

    for row in rows:
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and '|' in row:
            try:
                weight = int(row.split('|')[1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            total_int_sum = 0
            string_length_sum = 0
            for field in row:
                if isinstance(field, int) and not isinstance(field, bool):
                    total_int_sum += field
                elif isinstance(field, str):
                    string_length_sum += len(field)
            weight = total_int_sum + string_length_sum

        if (state + weight + original_index) % 11 != 5 or original_index == len(rows) - 1:
            kept_rows.append(row)
            original_index += 1
            state = 9 if weight == 0 else (3 * state + weight) % 11

    if not kept_rows:
        return []

    groups = {}
    for row in kept_rows:
        if isinstance(row, list) and len(row) >= 4:
            group = row[0]
            if group not in groups:
                groups[group] = []
            groups[group].append(row)

    result = []
    for group, rows_in_group in groups.items():
        scored_rows = []
        for row in rows_in_group:
            if isinstance(row, list) and len(row) >= 3:
                scored_rows.append((row[1], row[2], row[3]))

        scored_rows.sort(key=lambda x: (x[0], x[1], x[2]), reverse=True)
        best_row = scored_rows[0]
        result.append([group, best_row[2]])

    result.sort(key=lambda x: x[0])
    return result

